import {queryFor,safeRepo,formatCount,escapeHTML as e,canCompare} from './core.mjs';
const $=s=>document.querySelector(s);const $$=s=>[...document.querySelectorAll(s)];
const curated={
'localsend/localsend':'ينقل الملفات والرسائل بين أجهزتك عبر الشبكة المحلية. له تطبيقات جاهزة لعدة أنظمة، ومنها أندرويد.',
'ollama/ollama':'لتشغيل نماذج ذكاء اصطناعي محليًا. يحتاج إعدادًا واختيار نموذج يناسب ذاكرة الجهاز.',
'n8n-io/n8n':'لربط الخدمات وأتمتة المهام. راجع الترخيص وتكلفة الاستضافة والخدمات المتصلة.',
'Stirling-Tools/Stirling-PDF':'أدوات لمعالجة ملفات PDF وتحريرها. راجع طريقة التشغيل المناسبة لجهازك.',
'freeCodeCamp/freeCodeCamp':'منصة ومناهج لتعلم البرمجة. مستودع الكود نفسه ليس تطبيقًا جاهزًا للتثبيت.',
'sindresorhus/awesome':'فهرس لقوائم تجمع أدوات وموارد في مجالات كثيرة. نقطة بداية للاستكشاف.',
'public-apis/public-apis':'قائمة بواجهات برمجية يمكن استخدامها لربط التطبيقات بمصادر وخدمات؛ مناسبة للمطورين.',
'codecrafters-io/build-your-own-x':'مراجع لتعلم البرمجة ببناء تقنيات من الصفر. مشروع تعليمي، وليس برنامجًا جاهزًا.',
'donnemartin/system-design-primer':'مرجع لفهم تصميم الأنظمة والاستعداد للمقابلات التقنية.',
'jwasham/coding-interview-university':'خطة وموارد للتحضير للمقابلات البرمجية. تحتاج دراسة وممارسة.',
'vinta/awesome-python':'قائمة مكتبات وأدوات بايثون مرتبة حسب الاستخدام.',
'facebook/react':'مكتبة لبناء واجهات التطبيقات؛ تحتاج خبرة برمجية وبيئة تطوير.',
'EbookFoundation/free-programming-books':'قوائم بكتب وموارد لتعلم البرمجة بلغات متعددة.',
'kamranahmedse/developer-roadmap':'خرائط ومسارات لتعلم مهارات التطوير حسب التخصص.'};
function read(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}}
function write(key,data){try{localStorage.setItem(key,JSON.stringify(data));return true}catch{toast('تعذر الحفظ في المتصفح. بياناتك متاحة في الجلسة الحالية فقط.');return false}}
let saved=read('radar-saved-v1',{});if(!saved||typeof saved!=='object'||Array.isArray(saved))saved={};
for(const [k,v] of Object.entries(saved)){if(!safeRepo(v?.repo))delete saved[k]}
let state={view:'discover',category:'all',period:'all',search:'',sort:'stars',page:1,stage:'all'};let items=[],selected=[],known=new Map(),busy=false,controller,requestId=0,total=0,lastFetch=null,toastTimer;
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3200)}
function message(text,error=false){$('#message').textContent=text;$('#message').hidden=!text;$('#message').classList.toggle('error',error)}
function date(value){const d=new Date(value);return Number.isNaN(d.getTime())?'غير متاح':d.toLocaleDateString('ar',{year:'numeric',month:'short',day:'numeric'})}
function freshness(cached=false){$('#freshness').textContent=lastFetch?`${cached?'بيانات محفوظة · ':'آخر جلب ناجح · '}${date(lastFetch)} ${new Date(lastFetch).toLocaleTimeString('ar',{hour:'2-digit',minute:'2-digit'})}`:'لم يتم جلب بيانات بعد'}
function current(){if(state.view==='saved')return Object.values(saved).filter(x=>state.stage==='all'||x.stage===state.stage).map(x=>x.repo);return items}
function card(r){const s=saved[r.id];const desc=curated[r.full_name];return `<article class="card"><div class="card-top">${r.owner.avatar_url?`<img class="avatar" src="${e(r.owner.avatar_url)}" alt="" loading="lazy" referrerpolicy="no-referrer">`:'<span class="avatar"></span>'}<button class="bookmark ${s?'on':''}" data-save="${r.id}" aria-label="${s?'إزالة من مكتبتي':'حفظ في مكتبتي'}" aria-pressed="${!!s}">${s?'★':'☆'}</button></div><a class="repo-name" href="${e(r.html_url)}" target="_blank" rel="noopener noreferrer">${e(r.name)}</a><div class="owner">${e(r.owner.login)}</div>${desc?'<span class="arabic-tag">شرح عربي مختصر</span>':''}<p class="desc" dir="auto">${e(desc||r.description||'لا يوجد وصف من صاحب المشروع. افتح README لمعرفة التفاصيل.')}</p><div class="stats"><span>★ <b>${formatCount(r.stargazers_count)}</b></span><span>⑂ ${formatCount(r.forks_count)}</span><span><i class="lang-dot"></i>${e(r.language||'غير محددة')}</span></div><span class="activity">آخر نشاط للكود: ${date(r.pushed_at)}</span><div class="card-bottom"><a class="repo-link" href="${e(r.html_url)}" target="_blank" rel="noopener noreferrer">افتح المشروع ↗</a><label class="compare-label"><input type="checkbox" data-compare="${r.id}" ${selected.includes(r.id)?'checked':''}> قارن</label></div>${s?`<label class="stage">حالة التجربة <select data-stage="${r.id}">${[['interested','مهتم'],['try','سأجرّبه'],['using','أستخدمه']].map(([v,l])=>`<option value="${v}" ${s.stage===v?'selected':''}>${l}</option>`).join('')}</select></label>`:''}<button class="help" data-help="${r.id}">✧ انسخ طلب شرح وتشغيل بالعربي</button></article>`}
function render(){const list=current();list.forEach(r=>known.set(r.id,r));$('#cards').innerHTML=list.length?list.map(card).join(''):`<div class="empty"><h3>${busy?'بنجهّز المشاريع…':state.view==='saved'?'مكتبتك تبدأ باختيار واحد.':'لم نجد مشاريع بهذه الفلاتر.'}</h3><p>${state.view==='saved'?'اضغط ☆ على أي مشروع لحفظه هنا، ثم حدّد حالة تجربته.':'جرّب كلمة مختلفة أو مجالًا أوسع.'}</p></div>`;$('#saved-count').textContent=formatCount(Object.keys(saved).length);$('#results-count').textContent=state.view==='saved'?`${formatCount(list.length)} في مكتبتك`:`${formatCount(list.length)} معروض${total?' من '+formatCount(total)+' نتيجة':''}`;$('#more').hidden=state.view!=='discover'||items.length>=Math.min(total,1000)||items.length===0;$('#more').disabled=busy;$('#refresh').disabled=busy;$('#compare-bar').hidden=!selected.length;$('#compare-count').textContent=`${formatCount(selected.length)} / ٣ مشاريع`;$('#show-compare').disabled=selected.length<2}
function cacheKey(){return 'radar-cache:'+queryFor(state)+':'+state.sort+':'+state.page}
async function load(append=false){const myId=++requestId;controller?.abort();controller=new AbortController();busy=true;if(!append){items=[];state.page=1;total=0}message('');render();const key=cacheKey();let timeout;try{timeout=setTimeout(()=>controller?.abort(),18000);const url=new URL('https://api.github.com/search/repositories');url.search=new URLSearchParams({q:queryFor(state),sort:state.sort,order:'desc',per_page:'24',page:String(state.page)});const res=await fetch(url,{signal:controller.signal,headers:{Accept:'application/vnd.github+json'}});if(!res.ok){if(res.status===403||res.status===429){const reset=Number(res.headers.get('x-ratelimit-reset'));throw new Error('وصلنا لحد طلبات GitHub. '+(reset?'جرّب بعد '+new Date(reset*1000).toLocaleTimeString('ar',{hour:'2-digit',minute:'2-digit'}):'انتظر قليلًا ثم جرّب مجددًا.'))}throw new Error('تعذر جلب البيانات من GitHub ('+res.status+').')}const raw=await res.json();if(!Array.isArray(raw.items))throw new Error('استجابة GitHub غير متوقعة.');if(myId!==requestId)return;const data=raw.items.map(safeRepo).filter(Boolean);const seen=new Set(append?items.map(x=>x.id):[]);items=append?[...items,...data.filter(x=>!seen.has(x.id))]:data;total=raw.total_count;lastFetch=new Date().toISOString();write(key,{items:data,total,lastFetch});freshness();if(raw.incomplete_results)message('GitHub أعاد نتائج جزئية لهذه العملية.');if(state.search&&/[\u0600-\u06ff]/.test(state.search))message('نحوّل بعض كلمات البحث العربية الشائعة إلى كلمات مناسبة لـGitHub؛ ليست ترجمة ذكية شاملة.');for(const r of data)if(saved[r.id])saved[r.id].repo=r;write('radar-saved-v1',saved)}catch(err){if(myId!==requestId)return;let cache=read(key,null);if(!cache&&!append&&state.category==='all'&&state.period==='all'&&!state.search&&state.sort==='stars'){try{const r=await fetch('./snapshot.json');if(r.ok)cache=await r.json()}catch{}}
if(cache&&Array.isArray(cache.items)){const data=cache.items.map(safeRepo).filter(Boolean);items=append?[...items,...data]:data;total=cache.total;lastFetch=cache.lastFetch;freshness(true);message((err.name==='AbortError'?'انتهت مهلة الاتصال.':err.message)+' نعرض آخر نسخة محفوظة، وليست بيانات لحظية.',true)}else{if(append)state.page=Math.max(1,state.page-1);message(err.name==='AbortError'?'تأخر الاتصال. اضغط تحديث الآن للمحاولة.':err.message,true);freshness()}}finally{clearTimeout(timeout);if(myId===requestId){busy=false;render()}}}
function setView(view){state.view=view;$$('.nav').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('#view-title').textContent=view==='saved'?'مكتبتك، بطريقتك':view==='guide'?'خطوتك الأولى':'على رادارك';$('#guide').hidden=view!=='guide';$('#discovery-controls').hidden=view!=='discover';$('#library-controls').hidden=view!=='saved';$('#cards').hidden=view==='guide';$('.results-meta').hidden=view==='guide';message('');render();if(view==='discover'&&!items.length&&!busy)load();if(view==='guide')$('#more').hidden=true;$('#workspace').scrollIntoView({behavior:'smooth'})}
$$('.nav').forEach(b=>b.addEventListener('click',()=>setView(b.dataset.view)));$('#how').onclick=()=>setView('guide');
$('#search-form').onsubmit=ev=>{ev.preventDefault();state.search=$('#search').value.slice(0,200);load()};
$$('.chip').forEach(b=>b.onclick=()=>{state.category=b.dataset.category;$$('.chip').forEach(c=>c.classList.toggle('active',c===b));load()});
$$('.period').forEach(b=>b.onclick=()=>{state.period=b.dataset.period;$$('.period').forEach(c=>c.classList.toggle('active',c===b));load()});$('#sort').onchange=()=>{state.sort=$('#sort').value;load()};$('#stage-filter').onchange=()=>{state.stage=$('#stage-filter').value;render()};$('#more').onclick=()=>{state.page++;load(true)};$('#refresh').onclick=()=>{if(state.view==='discover')load();else{setView('discover');if(!busy)load()}};
$('#cards').addEventListener('click',async ev=>{const save=ev.target.closest('[data-save]');const help=ev.target.closest('[data-help]');if(save){const id=Number(save.dataset.save);if(saved[id])delete saved[id];else saved[id]={repo:known.get(id),stage:'interested'};write('radar-saved-v1',saved);render();toast(saved[id]?'اتحفظ في مكتبتك على هذا المتصفح':'تمت الإزالة من مكتبتك')}if(help){const r=known.get(Number(help.dataset.help));const prompt=`اشرح المشروع التالي بالعربي البسيط: ${r.html_url}\nما فائدته بمثال عملي؟ هل له تطبيق جاهز؟ ما الأجهزة المدعومة ومتطلبات التشغيل والتكلفة والترخيص؟ راجع تعليماته الحالية، ثم ساعدني أبدأ خطوة خطوة. لا تفترض أن عدد النجوم يضمن الجودة. اسألني عن جهازي وهدفي عند الحاجة.`;try{await navigator.clipboard.writeText(prompt);toast('تم النسخ. الصقه في محادثتك مع ChatGPT.')}catch{$('#comparison').innerHTML='<p>انسخ الطلب التالي والصقه في ChatGPT:</p><textarea style="width:100%;height:230px" readonly>'+e(prompt)+'</textarea>';$('#dialog').showModal()}}});
$('#cards').addEventListener('change',ev=>{if(ev.target.matches('[data-compare]')){const id=Number(ev.target.dataset.compare);if(!canCompare(selected,id)){ev.target.checked=false;toast('قارن حتى ٣ مشاريع في المرة الواحدة.');return}selected=selected.includes(id)?selected.filter(x=>x!==id):[...selected,id];render()}if(ev.target.matches('[data-stage]')){const id=Number(ev.target.dataset.stage);if(saved[id]){saved[id].stage=ev.target.value;write('radar-saved-v1',saved);render()}}});
$('#clear-compare').onclick=()=>{selected=[];render()};$('#close-dialog').onclick=()=>$('#dialog').close();$('#show-compare').onclick=()=>{const repos=selected.map(id=>known.get(id)).filter(Boolean);$('#comparison').innerHTML=`<p style="font-size:12px">مقارنة بيانات، وليست تقييمًا آليًا للجودة أو ملاءمة جهازك.</p><div class="comparison-grid" style="--columns:${repos.length}">${repos.map(r=>`<article><h3>${e(r.full_name)}</h3><p dir="auto">${e(curated[r.full_name]||r.description)}</p><p><small>النجوم</small>★ ${formatCount(r.stargazers_count)}</p><p><small>لغة البرمجة</small>${e(r.language||'غير محددة')}</p><p><small>الترخيص المعلن</small>${e(r.license?.spdx_id||'غير محدد — راجع المستودع')}</p><p><small>آخر نشاط للكود</small>${date(r.pushed_at)}</p><p><small>تاريخ الإنشاء</small>${date(r.created_at)}</p><p><small>ملاءمة جهازك والتكلفة</small>تحتاج مراجعة تعليمات المشروع</p><a class="repo-link" href="${e(r.html_url)}" target="_blank" rel="noopener noreferrer">افتح المشروع ↗</a></article>`).join('')}</div>`;$('#dialog').showModal()};
setInterval(()=>{if(!document.hidden&&state.view==='discover'&&!busy)load()},300000);load();
